// 取得圖片 ID 對應的分類 slug；找不到回傳 null
function getSpriteCategory(id) {
  if (!id) return null;
  const pure = id.replace(/\.(png|jpg|jpeg|webp|gif)$/i, '');
  return SPRITE_CATEGORY_MAP[pure] || null;
}

// v2.4.0：資源 manifest（{圖id: "相對於assets的子路徑"}）
// 啟動時 fetch 一次 /assets/assets-manifest.json，缺失時 fallback 到分類目錄邏輯
// v2.4.0-patch：新增 ASSETS_REV_INDEX（basename → value path）
//   因為 assetUrl 常收到單純 hash id（如 '0yfRk9msfe'），但 manifest key 是 'boss/0yfRk9msfe'
//   直接查不到 → 反向索引解決這個問題
let ASSETS_MANIFEST = null;
let ASSETS_MANIFEST_LOADED = false;
let ASSETS_REV_INDEX = null; // basename(無副檔名) → value path (assets/xxx/yyy.jpg)
function _buildRevIndex(manifest) {
  const rev = {};
  const keys = Object.keys(manifest);
  // 先掃描所有 key，收集每個 basename 的候選
  const candidates = {}; // basename -> [{key, value, category}]
  for (const k of keys) {
    const parts = k.split('/');
    const base = parts[parts.length - 1]; // key 不含副檔名
    const v = manifest[k];
    const cat = parts.length > 1 ? parts[0] : '';
    if (!candidates[base]) candidates[base] = [];
    candidates[base].push({ key: k, value: v, category: cat });
  }
  // 為每個 basename 選出優先級最高的：非 _old 結尾 > _old 結尾
  for (const base of Object.keys(candidates)) {
    const arr = candidates[base];
    if (arr.length === 1) {
      rev[base] = arr[0].value;
    } else {
      // 優先級：完全沒 _old > 有部分 _old
      const nonOld = arr.filter(x => !x.key.includes('_old'));
      if (nonOld.length > 0) {
        rev[base] = nonOld[0].value;
      } else {
        rev[base] = arr[0].value;
      }
    }
  }
  return rev;
}
function loadAssetsManifest() {
  if (ASSETS_MANIFEST_LOADED) return Promise.resolve(ASSETS_MANIFEST);
  return fetch('/assets/assets-manifest.json', { cache: 'no-cache' })
    .then(r => { if (!r.ok) throw new Error('manifest HTTP ' + r.status); return r.json(); })
    .then(data => {
      ASSETS_MANIFEST = data || {};
      ASSETS_REV_INDEX = _buildRevIndex(ASSETS_MANIFEST);
      ASSETS_MANIFEST_LOADED = true;
      console.log('[Assets] manifest 載入成功，共', Object.keys(ASSETS_MANIFEST).length, '筆；反向索引', Object.keys(ASSETS_REV_INDEX).length, '筆');
      return ASSETS_MANIFEST;
    })
    .catch(e => {
      ASSETS_MANIFEST = null;
      ASSETS_REV_INDEX = null;
      ASSETS_MANIFEST_LOADED = true;
      console.warn('[Assets] manifest 缺失，使用分類目錄 fallback:', e.message);
      return null;
    });
}

function assetUrl(id) {
  if (!id) return '';
  if (typeof id !== 'string') return id;
  // 已經是完整 URL / data URI → 原樣回傳
  if (id.startsWith('http') || id.startsWith('data:')) return id;
  // 以 / 開頭的絕對路徑（平台靜資 /spark/...） → 嘗試提取 id 走本地 manifest/分類
  if (id.startsWith('/')) {
    const sparkId = _extractCdnId(id);
    if (sparkId && (ASSETS_MANIFEST?.[sparkId] || getSpriteCategory(sparkId))) {
      // 本地有對應 → 走本地路徑
      if (ASSETS_MANIFEST?.[sparkId]) {
        const p = ASSETS_MANIFEST[sparkId];
        return p.startsWith('assets/') ? p : 'assets/' + p;
      }
      const cat = getSpriteCategory(sparkId);
      if (cat) return 'assets/' + cat + '/' + sparkId + '.png';
    }
    return id; // 沒對應就原樣回傳（由 onerror fallback 處理）
  }
  // 已經是 assets/ 開頭的本地路徑 → 原樣回傳（由 onerror fallback 處理）
  if (id.startsWith('assets/')) return id;
  // 從完整 CDN URL 中萃取出純 ID（防止重複包前綴）
  if (id.indexOf('aka.doubaocdn.com/s/') !== -1) {
    const m = id.match(/aka\.doubaocdn\.com\/s\/([^?#/\s"'<>]+)/);
    if (m && m[1]) id = m[1];
  }
  // 去除副檔名（png/jpg/jpeg/webp/gif）
  const pureId = id.replace(/\.(png|jpg|jpeg|webp|gif)$/i, '');
  // 根據環境決定優先路徑
  // v2.4.0：本地優先 → 分類目錄 assets/<slug>/<id>.png；CDN 優先 → 直接 CDN
  if (_preferCdn()) {
    return CDN_BASE + pureId;
  }
  // v2.4.0：manifest 優先級最高（若已載入且有此 id）
  if (ASSETS_MANIFEST_LOADED && ASSETS_MANIFEST && ASSETS_MANIFEST[pureId]) {
    const mpath = ASSETS_MANIFEST[pureId];
    // CDN URL 直接回傳（/spark/ 平台靜資或 http 開頭）
    if (mpath.startsWith('/spark/') || mpath.startsWith('http')) return mpath;
    // 路徑若已含 assets/ 前綴則直接用，否則加上
    if (mpath.startsWith('assets/')) return mpath;
    return 'assets/' + mpath;
  }
  // v2.4.0-patch：manifest 直接 key 查不到時 → 查反向索引（basename → path）
  // 解決「純 hash id 查不到（manifest key 是 category/hash）」導致全部 404 的問題
  if (ASSETS_MANIFEST_LOADED && ASSETS_REV_INDEX && ASSETS_REV_INDEX[pureId]) {
    const mpath = ASSETS_REV_INDEX[pureId];
    if (mpath.startsWith('/spark/') || mpath.startsWith('http')) return mpath;
    if (mpath.startsWith('assets/')) return mpath;
    return 'assets/' + mpath;
  }
  // v2.4.0：若 manifest 已載入且是含 / 的語意路徑，但不在 manifest → 繼續走下方 fallback
  // 純 hash id 若 manifest + rev index 都找不到 → 才視為棄用（返回空，避免 404）
  if (ASSETS_MANIFEST_LOADED && ASSETS_MANIFEST) {
    if (pureId.indexOf('/') === -1) {
      return '';
    }
  }
  // v2.4.0：語意路徑優先走 manifest；若不在 manifest，嘗試 jpg/png 並以 manifest 結果為準
  // 對於有 / 的語意路徑，優先嘗試 .jpg（多數美術圖為 jpg），其次 .png
  if (id.indexOf('/') !== -1) {
    // 有副檔名 → 直接拼接
    if (/\.(jpg|jpeg|png|webp|gif)$/i.test(id)) return 'assets/' + id;
    // 沒副檔名 → 先嘗試 .jpg（多數美術資源），fallback 到 .png（onerror 鏈接續）
    return 'assets/' + pureId + '.jpg';
  }
  const cat = getSpriteCategory(pureId);
  if (cat) return 'assets/' + cat + '/' + pureId + '.png';
  return 'assets/' + pureId + '.png';
}

// 從一個失敗的圖片 URL 中萃取出 CDN ID（用於 fallback 重試）
function _extractCdnId(src) {
  if (!src) return '';
  // CDN URL → 直接取最後一段
  if (src.indexOf('aka.doubaocdn.com/s/') !== -1) {
    const m = src.match(/aka\.doubaocdn\.com\/s\/([^?#/\s"'<>]+)/);
    if (m && m[1]) return m[1].replace(/\.(png|jpg|jpeg|webp|gif)$/i, '');
  }
  // 本地 assets/ 路徑 → 取檔名去掉副檔名作為 ID
  // 例：assets/warrior/idle.png → warrior_idle （拼出組合 ID，CDN 上若有同名檔可載入）
  // 但更常見的是「檔名即 ID」的情況，所以這裡優先取 basename
  if (src.indexOf('assets/') !== -1) {
    // 取最後一段檔名去掉副檔名
    const m = src.match(/assets\/.*\/([^./?#]+)\.(png|jpg|jpeg|webp|gif)/i);
    if (m && m[1]) return m[1];
    // 另一種：assets/ID.png（根目錄）
    const m2 = src.match(/assets\/([^./?#]+)\.(png|jpg|jpeg|webp|gif)/i);
    if (m2 && m2[1]) return m2[1];
  }
  // 平台靜資 /spark/.../static%2FID_ve_miaoda → 取 ID_ve_miaoda 當作 cdn id 試試
  if (src.indexOf('/spark/') !== -1) {
    const m = src.match(/static%2F([^/?#]+)/);
    if (m && m[1]) return decodeURIComponent(m[1]);
    const m2 = src.match(/static\/([^/?#]+)/);
    if (m2 && m2[1]) return m2[1];
  }
  return '';
}

// 圖片載入失敗備援：
//   本地 assets/ 失敗 → 切換到 CDN
//   CDN 失敗 → 隱藏圖片並為父層加上背景占位（避免顯示破裂圖示）
// 圖片載入失敗備援（v2.4.0 三層 fallback）：
//   1. assets/<分類>/<id>.png 失敗 → 嘗試 assets/<id>.png（舊扁平結構）
//   2. 扁平結構也失敗 → 切換到 CDN
//   3. CDN 失敗 → 隱藏圖片並為父層加上背景占位
function handleImgError(img) {
  if (!img || img.dataset.errFallback === 'fail') return;
  const src = img.src || '';

  // ===== v2.4.0：精靈 frame 圖片失敗 → 直接替換成 idle frame，絕不閃爍/透明 =====
  if (img.classList && img.classList.contains('unit-sprite-img')) {
    // 已經處理過就跳過
    if (img.dataset.errFallback === 'sprite_fixed') return;
    const unitEl = img.closest && img.closest('.world-unit');
    const idleImg = unitEl ? unitEl.querySelector('.sprite-frame-idle') : null;
    if (idleImg && idleImg !== img && idleImg.src) {
      img.dataset.errFallback = 'sprite_fixed';
      img.classList.add('frame-error');
      // 替換為 idle 的 src，確保畫面顯示的是有效圖而非破圖/透明
      img.src = idleImg.src;
      img.style.opacity = '1';
      img.style.visibility = 'visible';
      return;
    }
    // 連 idle 都找不到 → 最少要確保不透明不閃爍
    img.dataset.errFallback = 'sprite_fixed';
    img.classList.add('frame-error');
    img.style.opacity = '1';
    img.style.visibility = 'visible';
    return;
  }

  // 已經走過 CDN 還是失敗 → 最終 fallback
  // v2.4.0：不再隱藏圖片，改為顯示暗色漸層+文字兜底，絕不出現藍底問號或原生破圖
  if (img.dataset.errFallback === 'cdn') {
    img.dataset.errFallback = 'fail';
    // 隱藏自身，但父層加上帶名稱的漸層占位
    img.style.visibility = 'hidden';
    img.style.opacity = '0';
    if (img.parentElement && !img.parentElement.dataset.imgErrorBg) {
      img.parentElement.dataset.imgErrorBg = '1';
      const name = img.alt || img.dataset.unitName || '';
      const initial = name ? name.charAt(0) : '';
      img.parentElement.style.background = 'radial-gradient(ellipse at 50% 60%, rgba(80,60,40,0.85), rgba(20,15,10,0.95) 75%)';
      // 若父層還沒有兜底文字，加一個
      if (!img.parentElement.querySelector('.img-fallback-text')) {
        const fb = document.createElement('div');
        fb.className = 'img-fallback-text';
        fb.textContent = initial || '◆';
        fb.style.cssText = 'position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);color:rgba(210,180,120,0.6);font-size:24px;font-weight:700;pointer-events:none;letter-spacing:1px;';
        img.parentElement.style.position = img.parentElement.style.position || 'relative';
        img.parentElement.appendChild(fb);
      }
    }
    return;
  }

  // 分類目錄失敗 → 嘗試扁平結構 assets/<id>.png
  if (img.dataset.errFallback === 'cat') {
    const cdnId = _extractCdnId(src);
    if (cdnId) {
      img.dataset.errFallback = 'flat';
      img.src = 'assets/' + cdnId + '.png';
      return;
    }
    // 抽不出 ID，直接跳 CDN
    img.dataset.errFallback = 'cdn';
    const cid = _extractCdnId(src);
    if (cid) { img.src = CDN_BASE + cid; return; }
    // 連 CDN ID 都抽不出 → 最終
    img.dataset.errFallback = 'fail';
    img.style.visibility = 'hidden';
    img.style.opacity = '0';
    if (img.parentElement && !img.parentElement.dataset.imgErrorBg) {
      img.parentElement.dataset.imgErrorBg = '1';
      img.parentElement.style.background = 'radial-gradient(ellipse at 50% 60%, rgba(120,90,50,0.25), transparent 70%)';
    }
    return;
  }

  // 扁平結構失敗 → 嘗試 CDN
  if (img.dataset.errFallback === 'flat') {
    const cdnId = _extractCdnId(src);
    if (cdnId) {
      img.dataset.errFallback = 'cdn';
      img.src = CDN_BASE + cdnId;
      return;
    }
    img.dataset.errFallback = 'fail';
    img.style.visibility = 'hidden';
    img.style.opacity = '0';
    if (img.parentElement && !img.parentElement.dataset.imgErrorBg) {
      img.parentElement.dataset.imgErrorBg = '1';
      img.parentElement.style.background = 'radial-gradient(ellipse at 50% 60%, rgba(120,90,50,0.25), transparent 70%)';
    }
    return;
  }

  // 第一次失敗：判斷來源
  const cdnId = _extractCdnId(src);

  // 如果本來就是 CDN → 直接 fail
  if (src.indexOf('aka.doubaocdn.com/') !== -1) {
    img.dataset.errFallback = 'fail';
    img.style.visibility = 'hidden';
    img.style.opacity = '0';
    if (img.parentElement && !img.parentElement.dataset.imgErrorBg) {
      img.parentElement.dataset.imgErrorBg = '1';
      img.parentElement.style.background = 'radial-gradient(ellipse at 50% 60%, rgba(120,90,50,0.25), transparent 70%)';
    }
    return;
  }

  // 如果本來是分類目錄路徑（assets/xx/yy.png，含兩層以上）→ 先嘗試扁平
  if (src.indexOf('assets/') !== -1) {
    const m = src.match(/assets\/[^/]+\/([^./?#]+)\./i);
    if (m && m[1]) {
      // 來自分類目錄 → 下一層試扁平
      img.dataset.errFallback = 'cat';
      img.src = 'assets/' + m[1] + '.png';
      return;
    }
    // 扁平結構失敗 → 試 CDN
    const flatM = src.match(/assets\/([^./?#]+)\./i);
    if (flatM && flatM[1] && cdnId) {
      img.dataset.errFallback = 'flat';
      img.src = CDN_BASE + cdnId;
      return;
    }
  }

  // /spark/ 平台靜資失敗 → 先試本地分類目錄 assets/<slug>/<id>.png
  if (src.indexOf('/spark/') !== -1 && cdnId) {
    const cat = getSpriteCategory(cdnId);
    if (cat) {
      img.dataset.errFallback = 'cat';
      img.src = 'assets/' + cat + '/' + cdnId + '.png';
      return;
    }
    // 沒有分類 → 直接試扁平 assets/<id>.png
    img.dataset.errFallback = 'flat';
    img.src = 'assets/' + cdnId + '.png';
    return;
  }

  // 什麼都抽不出 → 最終 fallback
  img.dataset.errFallback = 'fail';
  img.style.visibility = 'hidden';
  img.style.opacity = '0';
  if (img.parentElement && !img.parentElement.dataset.imgErrorBg) {
    img.parentElement.dataset.imgErrorBg = '1';
    img.parentElement.style.background = 'radial-gradient(ellipse at 50% 60%, rgba(120,90,50,0.25), transparent 70%)';
  }
}

// 全域 img 錯誤捕獲：補捉所有沒寫 onerror 的 <img>
// 使用 capture 階段攔截，確保比元素自身的 onerror 更早觸發（或補足沒寫的）
document.addEventListener('error', function (e) {
  const target = e.target;
  if (!target || target.tagName !== 'IMG') return;
  // 已經由 handleImgError 處理過的就跳過
  if (target.dataset.errFallback === 'fail' || target.dataset.errFallback === 'cdn') return;
  // 標註由全域監聽處理，避免和元素自帶的 onerror 重複
  if (!target.dataset.globalErr) {
    target.dataset.globalErr = '1';
    handleImgError(target);
  }
}, true);

// 背景圖（CSS background-image）失敗偵測：用 Image 對象預載
// safeBackgroundUrl 快取：已確認可用的 URL 直接設定，不再重複預載
const _bgUrlCache = new Map(); // key: url, value: 'ok' | 'cdn_ok' | 'fail'
const _bgPending = new Map();  // key: url, value: Promise

// 用法：safeBackgroundUrl(element, url) — 設背景圖，失敗時自動 fallback CDN
// 支援三類 URL：本地 assets/、CDN URL、/spark/ 平台靜資路徑
// fallback 順序：原 URL → CDN（用 _extractCdnId 抽 ID 重試）→ 柔和漸層占位
function safeBackgroundUrl(el, url) {
  if (!el || !url) return;
  // 先查快取：確認過可用的 URL 直接套用
  const cached = _bgUrlCache.get(url);
  if (cached === 'ok') {
    el.style.backgroundImage = 'url(' + url + ')';
    return;
  }
  if (cached === 'cdn_ok') {
    const cdnId = _extractCdnId(url);
    if (cdnId) {
      el.style.backgroundImage = 'url(' + CDN_BASE + cdnId + ')';
      return;
    }
  }
  if (cached === 'fail') {
    el.style.backgroundImage = 'radial-gradient(ellipse at 50% 60%, rgba(120,90,50,0.25), transparent 70%)';
    return;
  }
  // 相同 URL 正在載入中：複用 Promise，不重複 new Image
  const pending = _bgPending.get(url);
  if (pending) {
    pending.then(function(result) {
      if (result === 'ok') {
        el.style.backgroundImage = 'url(' + url + ')';
      } else if (result === 'cdn_ok') {
        const cdnId = _extractCdnId(url);
        if (cdnId) el.style.backgroundImage = 'url(' + CDN_BASE + cdnId + ')';
      } else {
        el.style.backgroundImage = 'radial-gradient(ellipse at 50% 60%, rgba(120,90,50,0.25), transparent 70%)';
      }
    });
    return;
  }

  const testImg = new Image();
  const promise = new Promise(function(resolve) {
    testImg.onload = function () {
      _bgUrlCache.set(url, 'ok');
      el.style.backgroundImage = 'url(' + url + ')';
      resolve('ok');
    };
    testImg.onerror = function () {
      // 第一次失敗：嘗試 CDN（不論是 assets/ 還是 /spark/ 還是 CDN 本身）
      const cdnId = _extractCdnId(url);
      if (cdnId && !url.startsWith(CDN_BASE)) {
        const cdnUrl = CDN_BASE + cdnId;
        const test2 = new Image();
        test2.onload = function () {
          _bgUrlCache.set(url, 'cdn_ok');
          el.style.backgroundImage = 'url(' + cdnUrl + ')';
          resolve('cdn_ok');
        };
        test2.onerror = function () {
          _bgUrlCache.set(url, 'fail');
          el.style.backgroundImage = 'radial-gradient(ellipse at 50% 60%, rgba(120,90,50,0.25), transparent 70%)';
          resolve('fail');
        };
        test2.src = cdnUrl;
      } else {
        _bgUrlCache.set(url, 'fail');
        el.style.backgroundImage = 'radial-gradient(ellipse at 50% 60%, rgba(120,90,50,0.25), transparent 70%)';
        resolve('fail');
      }
    };
    testImg.src = url;
  }).then(function(r) {
    _bgPending.delete(url);
    return r;
  });
  _bgPending.set(url, promise);
}

