// ==================== 多人連線輔助 ====================
// 更新連線狀態小圓點（設定按鈕右上角）
function updateMultiplayerStatus(status) {
  const S = window.MultiplayerClient ? MultiplayerClient.STATUS : {};
  const dot = document.getElementById('mp-status-dot');
  const txt = document.getElementById('mp-status-text');
  const btn = document.getElementById('mp-connect-btn');
  const s = status || S.OFFLINE;
  // 狀態點
  if (dot) {
    dot.className = 'mp-status-dot mp-status-' + s;
    const titles = {
      offline: '連線中',
      loading: '載入中...',
      connecting: '連線中...',
      online: '已連線多人',
      reconnecting: '斷線重連中...',
      error: '連線失敗',
    };
    dot.title = titles[s] || '';
  }
  // 設定面板狀態文字
  if (txt) {
    txt.className = 'mp-status-text mp-status-' + s;
    const labels = {
      offline: '連線中',
      loading: '載入中...',
      connecting: '連線中，伺服器可能喚醒中',
      online: '已連線',
      reconnecting: '斷線重連中',
      error: '連線失敗',
    };
    txt.textContent = labels[s] || '連線中';
  }
  // 連線按鈕文字
  if (btn) {
    if (s === S.ONLINE || s === S.RECONNECTING || s === S.CONNECTING || s === S.LOADING) {
      btn.textContent = '斷線';
      btn.dataset.connected = '1';
    } else {
      btn.textContent = '連線';
      btn.dataset.connected = '0';
    }
  }
}

// 舊函式名稱保留相容
try { updateMultiplayerStatusDot = function(online) { updateMultiplayerStatus(online ? 'online' : 'offline'); }; } catch(e) {}

// 初始化多人連線 UI（設定面板打開時同步輸入框內容）
function initMultiplayerUI() {
  if (!window.MultiplayerClient) return;
  const input = el.mpServerInput;
  if (input) input.value = MultiplayerClient.getSavedServerUrl() || '';
  // 繫結連線按鈕
  if (el.mpConnectBtn) {
    // 先移除舊監聽（避免重複）
    const newBtn = el.mpConnectBtn.cloneNode(true);
    el.mpConnectBtn.parentNode.replaceChild(newBtn, el.mpConnectBtn);
    el.mpConnectBtn = newBtn;
    el.mpConnectBtn.addEventListener('click', () => {
      const S = MultiplayerClient.STATUS;
      const cur = MultiplayerClient.status;
      if (cur === S.ONLINE || cur === S.CONNECTING || cur === S.RECONNECTING || cur === S.LOADING) {
        MultiplayerClient.disconnect();
      } else {
        const url = el.mpServerInput ? el.mpServerInput.value.trim() : '';
        if (!url) { alert('請輸入伺服器位址'); return; }
        MultiplayerClient.connect(url, (window.AuthSystem && AuthSystem.getToken) ? AuthSystem.getToken() : '').catch(err => {
          console.warn('[MP UI] connect failed:', err);
        });
      }
    });
  }
  // 狀態回調
  MultiplayerClient.setStatusCallback((s) => {
    try { updateMultiplayerStatus(s); } catch (e) { /* ignore */ }
  });
  // 聊天回調：接到現有聊天視窗
  MultiplayerClient.setChatCallback((msg) => {
    try {
      if (typeof addLog === 'function' && msg && msg.name && msg.text) {
        const ch = msg.channel || 'world';
        // 映射到現有聊天頻道（world → system 標籤，用 chat 類型顯示）
        const targetCh = (ch === 'world' || ch === 'all') ? 'general' : ch;
        addLog('chat-online', `【${msg.name}】：${msg.text}`, targetCh);
      }
    } catch (e) { console.error('mp chat cb error:', e); }
  });
  // 怪物傷害回調（其他玩家造成的傷害特效）
  MultiplayerClient.setMonsterDamageCallback((d) => {
    try {
      if (typeof showDamage === 'function' && d.monsterId) {
        showDamage(d.x, d.y - 50, d.damage, d.isCrit ? 'crit' : 'normal');
      }
    } catch (e) { /* ignore */ }
  });
  // 怪物擊殺回調
  MultiplayerClient.setMonsterKilledCallback((d) => {
    try {
      if (typeof addLog === 'function' && d.killerName) {
        addLog('system', `【${d.killerName}】擊敗了怪物`, 'world');
      }
    } catch (e) { /* ignore */ }
  });
  // 獎勵回調
  MultiplayerClient.setGainRewardCallback((r) => {
    try {
      if (typeof addLog === 'function') {
        const parts = [];
        if (r.exp) parts.push(`經驗 +${r.exp}`);
        if (r.gold) parts.push(`金幣 +${r.gold}`);
        if (r.gem) parts.push(`鑽石 +${r.gem}`);
        if (parts.length > 0) addLog('system', `多人獎勵：${parts.join('，')}`, 'world');
      }
      if (r.exp && GS.player) GS.player.exp += r.exp;
      if (r.gold && GS.resources) GS.resources.gold += r.gold;
      if (r.gem && GS.resources) GS.resources.gem += r.gem;
      if (typeof updateUI === 'function') updateUI();
    } catch (e) { console.error('gain_reward error:', e); }
  });
  // 初始狀態
  updateMultiplayerStatus(MultiplayerClient.status);
}

// 同步玩家資料到多人伺服器（升級 / 變身 / 改名 / 換國家 時呼叫）
function syncMultiplayerProfile() {
  if (!window.MultiplayerClient || !MultiplayerClient.connected) return;
  try {
    MultiplayerClient.updateProfile({
      name: GS.player?.name,
      classId: GS.player?.classId,
      level: GS.player?.level,
      transformId: GS.player?.transformId || null,
      nation: GS.nation || null,
    });
  } catch (e) { /* ignore */ }
}

// ==================== 初始化 ====================
// ==================== 遊戲初始化 ====================
// v2.5.6：init 冪等化，只執行一次（避免重複繫結事件、重複啟動 game loop）
let _initDone = false;
function init() {
  if (_initDone) {
    console.log('[Init] 已初始化過，跳過重複呼叫');
    return;
  }
  _initDone = true;
  try {
    _initCore();
  } catch (e) {
    console.error('[Init] 嚴重錯誤：init 中途崩潰，仍嘗試啟動遊戲主循環以避免黑屏', e);
    // 顯示錯誤提示給玩家（v2.4.0：不再靜默黑屏）
    showInitError(e);
    // 嘗試恢復：若 loadMap / createPlayerSprite 沒跑完，補上最小可運行狀態
    try {
      if (sceneBg && !sceneBg.style.backgroundImage) {
        // 沒有背景也至少給一個漸層底，避免全黑
        sceneBg.style.background = 'radial-gradient(ellipse at 50% 60%, #1a120a 0%, #0a0705 100%)';
      }
      if (GS && GS.player) {
        if (typeof recalcStats === 'function') recalcStats();
      }
      if (typeof updateUI === 'function') {
        try { updateUI(); } catch(_) {}
      }
    } catch (_) {}
  }
  // 無論 init 是否成功，都啟動 gameLoop，保證畫面至少有回應
  requestAnimationFrame(gameLoop);
}

// v2.4.0：manifest 載入後刷新所有 sprite 圖片路徑（玩家、怪物、NPC）
function refreshAllSprites() {
  try {
    const unit = worldLayer?.querySelector('.world-unit.hero');
    if (unit && typeof updatePlayerSprite === 'function') updatePlayerSprite();
  } catch (e) {}
  try {
    if (GS.monsters) {
      GS.monsters.forEach(m => {
        const el = worldLayer?.querySelector('[data-id="' + m.uid + '"]');
        if (el && typeof updateMonsterSprite === 'function') updateMonsterSprite(m);
      });
    }
  } catch (e) {}
  try {
    if (typeof renderNPCs === 'function' && GS.currentMap) {
      const allMaps = getAllMaps();
      if (allMaps && allMaps[GS.currentMap]) renderNPCs(allMaps[GS.currentMap]);
    }
  } catch (e) {}
  console.log('[Assets] 所有 sprite 路徑已刷新');
}

function showInitError(err) {
  let box = $('init-error-box');
  if (!box) {
    box = document.createElement('div');
    box.id = 'init-error-box';
    box.style.cssText = 'position:fixed;inset:0;z-index:99999;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.85);font-family:inherit;';
    const inner = document.createElement('div');
    inner.style.cssText = 'max-width:420px;padding:24px 28px;background:linear-gradient(135deg,#2a1a0a,#120a04);border:1px solid #c03030;border-radius:8px;color:#f0d8a0;box-shadow:0 0 40px rgba(200,40,40,0.3);';
    inner.innerHTML = `
      <div style="font-size:18px;font-weight:700;color:#ff8060;letter-spacing:3px;margin-bottom:10px;">初 始 化 失 敗</div>
      <div style="font-size:12px;color:#b8a878;line-height:1.7;margin-bottom:12px;">遊戲初始化過程中發生錯誤，已嘗試恢復基本功能。若仍無法遊戲，請重新整理頁面。</div>
      <div id="init-error-detail" style="font-size:11px;color:#e0a060;background:rgba(0,0,0,0.4);padding:10px 12px;border-radius:4px;font-family:monospace;white-space:pre-wrap;word-break:break-all;max-height:180px;overflow-y:auto;"></div>
      <div style="margin-top:16px;text-align:right;">
        <button onclick="document.getElementById('init-error-box').style.display='none'" style="padding:6px 18px;background:linear-gradient(180deg,#a07820,#7a5a10);border:1px solid #c8a040;color:#fff;border-radius:3px;cursor:pointer;font-family:inherit;font-size:12px;">先試試看</button>
        <button onclick="location.reload()" style="margin-left:8px;padding:6px 18px;background:linear-gradient(180deg,#c04030,#802020);border:1px solid #e06050;color:#fff;border-radius:3px;cursor:pointer;font-family:inherit;font-size:12px;">重新整理</button>
      </div>
    `;
    box.appendChild(inner);
    document.body.appendChild(box);
  }
  const detail = $('init-error-detail');
  if (detail) {
    detail.textContent = (err && (err.stack || err.message)) || String(err);
  }
  box.style.display = 'flex';
}

