// v2.4.0：有四方向+攻擊真圖的單位清單（用 frames/ 子目錄結構）
// key 為方向檔案夾名，cat 為分類
const DIRECTIONAL_SPRITES_DIRKEY = {
  warrior:            { cat: '01_class' },
  archer:             { cat: '01_class' },
  mage:               { cat: '01_class' },
  rogue:              { cat: '01_class' },
  paladin:            { cat: '01_class' },
  illusionist:        { cat: '01_class' },
  dark_elf_assassin:  { cat: '01_class' },
  death_knight:       { cat: '02_transform' },
  baphomet:           { cat: '02_transform' },
  ishti:              { cat: '02_transform' },
  goblin:             { cat: '04_monster' },
  skeleton_warrior:   { cat: '04_monster' },
  giant_spider:       { cat: '04_monster' },
  werewolf:           { cat: '04_monster' },
};
// 執行期初始化：建立 idleId → dirKey 的快取（第一次使用時從 SPRITE 物件遍歷比對）
let _dirSpriteByIdleCache = null;
function _buildDirSpriteCache() {
  _dirSpriteByIdleCache = {};
  for (const [dirKey, info] of Object.entries(DIRECTIONAL_SPRITES_DIRKEY)) {
    // 從 SPRITE 物件中找 idle 路徑對應的 sprite
    const dirDownPath = assetUrl(info.cat + '/frames/' + dirKey + '/down.jpg');
    // 同時嘗試各種常見的 sprite key 對應
    if (SPRITE[dirKey]) {
      const idleUrl = SPRITE[dirKey].idle;
      // 萃取出 idle 的 id (最後一段，不含副檔名)
      const m = idleUrl.match(/([^/]+)\.(jpg|png|jpeg)$/i);
      if (m) {
        _dirSpriteByIdleCache[m[1]] = dirKey;
      }
    }
  }
}
function getDirKeyFromSprite(s) {
  if (!s || !s.idle) return null;
  if (!_dirSpriteByIdleCache) _buildDirSpriteCache();
  const m = s.idle.match(/([^/]+)\.(jpg|png|jpeg)$/i);
  if (!m) return null;
  return _dirSpriteByIdleCache[m[1]] || null;
}
function hasDirectionalSprites(s) {
  return !!getDirKeyFromSprite(s);
}
function getDirSpriteUrl(s, frame) {
  const dirKey = getDirKeyFromSprite(s);
  if (!dirKey) return null;
  const info = DIRECTIONAL_SPRITES_DIRKEY[dirKey];
  if (!info) return null;
  return assetUrl(info.cat + '/frames/' + dirKey + '/' + frame + '.jpg');
}

// ==================== 精靈圖 HTML（完整 8 幀模式 + 方向驅動） =====================
// v2.6.0：徹底重寫動畫引擎
//   - walk 4 張圖 = 4 個方向各 1 張（down/side/up/side），不是同一方向的 4 步
//   - 走路時：按當前方向取對應 walk 圖，與 idle 之間 ~120ms 來回切換 + 上下 bob 模擬踏步
//   - 攻擊時：attack_1 → attack_2 → attack_3 依次播放，每幀 ~100ms，播完回 idle/walk
//   - 受擊時：短顯 hit 幀 (~200ms) 後回到原狀態
//   - 朝左：scaleX(-1) 水平鏡射（只有 side 方向走這個分支）
//   - 精靈永遠是完整角色圖，不用圓框/濾鏡/肖像卡
// ==============================================================================

// 動畫狀態機：每個 unit 有獨立狀態
//   state: 'idle' | 'walk' | 'attack' | 'hit' | 'dead'
//   dir:   'down' | 'up' | 'left' | 'right'
//   phase: 0=idleFrame, 1=walkFrame (用於踏步來回)
//   attackIdx: 0/1/2 (攻擊第幾幀)
//   timer: 當前幀剩餘時間 ms

const ANIM_V260_CONFIG = {
  walkStepMs: 130,      // 每步 (idle↔walk) 切換週期的一半，約 120-150ms/幀
  attackFrameMs: 100,   // 攻擊每幀 ~100ms，3 幀共 300ms
  hitMs: 200,           // 受擊顯示時長
  bobPx: 2,             // 走路上下 bob 幅度
};

// 取得某 unit 當前應顯示的 sprite 圖片 URL（依狀態 + 方向）
function getUnitFrameSrc(unitAnim, spriteObj) {
  if (!spriteObj || !spriteObj.useImg) return null;
  const state = unitAnim.state;
  const dir = unitAnim.dir || 'down';
  
  if (state === 'dead') return spriteObj.hit || spriteObj.idle; // 死亡暫用 hit 或 idle，會走 tomb
  if (state === 'hit') return spriteObj.hit || spriteObj.idle;
  
  if (state === 'attack') {
    const idx = unitAnim.attackIdx || 0;
    if (idx === 0) return spriteObj.attack || spriteObj.idle;
    if (idx === 1) return spriteObj.attack2 || spriteObj.attack || spriteObj.idle;
    return spriteObj.attack3 || spriteObj.attack2 || spriteObj.attack || spriteObj.idle;
  }
  
  if (state === 'walk') {
    // 踏步：phase=0 顯示 walk[方向]，phase=1 顯示 idle，來回切換
    if (unitAnim.phase === 0) {
      if (dir === 'down') return spriteObj.walk || spriteObj.idle;
      if (dir === 'up') return spriteObj.walk3 || spriteObj.walk || spriteObj.idle;
      // left / right 都用 walk_side (walk2)
      return spriteObj.walk2 || spriteObj.walk || spriteObj.idle;
    } else {
      return spriteObj.idle;
    }
  }
  
  // idle
  return spriteObj.idle;
}

// 判斷是否需要水平鏡射（只有朝左時）
function shouldFlipLeft(unitAnim) {
  return unitAnim.dir === 'left';
}

// 將動畫狀態應用到 DOM（單張主 img，直接改 src + transform）
function applyAnimToDom(unitEl, unitAnim, spriteObj) {
  if (!unitEl || !spriteObj || !spriteObj.useImg) return;
  
  // 找主顯示 img（8 幀模式下使用 sprite-frame-idle 作為主顯示圖，直接改 src）
  const mainImg = unitEl.querySelector('.sprite-frame-idle');
  if (!mainImg) return;
  
  const src = getUnitFrameSrc(unitAnim, spriteObj);
  if (src && mainImg.src !== src) {
    mainImg.src = src;
  }
  
  // 水平鏡射
  const flip = shouldFlipLeft(unitAnim);
  mainImg.style.transform = flip ? 'scaleX(-1)' : 'none';
  
  // 走路 bob：phase 切換時輕微上下移動
  const wrap = unitEl.querySelector('.unit-sprite-wrap');
  if (wrap) {
    if (unitAnim.state === 'walk' && unitAnim.phase === 0) {
      mainImg.style.marginTop = '0px';
    } else if (unitAnim.state === 'walk') {
      mainImg.style.marginTop = ANIM_V260_CONFIG.bobPx + 'px';
    } else {
      mainImg.style.marginTop = '0px';
    }
  }
  
  // 其他 frame 全部隱藏（避免舊 frame 殘留）
  const allFrames = unitEl.querySelectorAll('.unit-sprite-img:not(.sprite-frame-idle)');
  for (let i = 0; i < allFrames.length; i++) {
    allFrames[i].style.display = 'none';
  }
  mainImg.style.display = 'block';
  
  // tomb 顯示
  const tomb = unitEl.querySelector('.unit-sprite-tomb');
  if (tomb) tomb.style.display = unitAnim.state === 'dead' ? 'flex' : 'none';
}

// 推進一個 unit 的動畫狀態（dtMs 毫秒）
function tickUnitAnim(uid, dtMs, spriteObj, unitEl) {
  const anim = unitAnimState.get(uid);
  if (!anim) return;
  
  // 死亡：不動
  if (anim.state === 'dead') return;
  
  anim.timer -= dtMs;
  if (anim.timer > 0) {
    // 時間沒到，但如果狀態變了立即刷新顯示
    if (anim._dirtyDisplay) {
      applyAnimToDom(unitEl, anim, spriteObj);
      anim._dirtyDisplay = false;
    }
    return;
  }
  
  // 時間到，進入下一階段
  if (anim.state === 'walk') {
    // 踏步：phase 在 0 和 1 之間來回
    anim.phase = 1 - (anim.phase || 0);
    anim.timer = ANIM_V260_CONFIG.walkStepMs;
  } else if (anim.state === 'attack') {
    // 攻擊：0 → 1 → 2 → 結束(回到原狀態)
    if (anim.attackIdx < 2) {
      anim.attackIdx++;
      anim.timer = ANIM_V260_CONFIG.attackFrameMs;
    } else {
      // 攻擊結束，回到 walk 或 idle
      anim.state = anim._postAttackState || 'idle';
      anim.attackIdx = 0;
      anim.phase = 0;
      anim.timer = ANIM_V260_CONFIG.walkStepMs;
    }
  } else if (anim.state === 'hit') {
    // 受擊結束，回到原狀態
    anim.state = anim._postHitState || 'idle';
    anim.timer = ANIM_V260_CONFIG.walkStepMs;
  } else {
    // idle：不推進
    anim.timer = 99999;
  }
  
  applyAnimToDom(unitEl, anim, spriteObj);
}

// 切換動畫狀態（外部調用：開始走路/停止/開打/受擊）
function setUnitAnimState(uid, newState, opts = {}) {
  let anim = unitAnimState.get(uid);
  if (!anim) {
    anim = { state: 'idle', dir: 'down', phase: 0, attackIdx: 0, timer: 0, _dirtyDisplay: true };
    unitAnimState.set(uid, anim);
  }
  
  if (newState === anim.state) {
    // 同狀態：只更新方向
    if (opts.dir && opts.dir !== anim.dir) {
      anim.dir = opts.dir;
      anim._dirtyDisplay = true;
    }
    return;
  }
  
  // 狀態切換
  const prevState = anim.state;
  
  if (newState === 'walk') {
    anim.state = 'walk';
    anim.dir = opts.dir || anim.dir || 'down';
    anim.phase = 0;
    anim.timer = ANIM_V260_CONFIG.walkStepMs;
  } else if (newState === 'attack') {
    // 記住攻擊前的狀態，播完回那狀態
    anim._postAttackState = prevState === 'walk' ? 'walk' : 'idle';
    anim.state = 'attack';
    anim.dir = opts.dir || anim.dir || 'down';
    anim.attackIdx = 0;
    anim.timer = ANIM_V260_CONFIG.attackFrameMs;
  } else if (newState === 'hit') {
    anim._postHitState = prevState === 'walk' ? 'walk' : 'idle';
    anim.state = 'hit';
    anim.timer = ANIM_V260_CONFIG.hitMs;
  } else if (newState === 'dead') {
    anim.state = 'dead';
    anim.timer = 99999;
  } else {
    // idle
    anim.state = 'idle';
    anim.dir = opts.dir || anim.dir || 'down';
    anim.phase = 0;
    anim.timer = 99999;
  }
  
  anim._dirtyDisplay = true;
}

// 彻底避免多帧堆叠问题
function buildSpriteHTML(spriteObj, kind, lean) {
  const size = SPRITE_SIZE[kind] || SPRITE_SIZE.hero;
  const s = typeof spriteObj === 'object' && spriteObj ? spriteObj : SPRITE.goblin;
  const color = s.color || '#c0a060';
  const glow = s.glow || '#ffe090';
  const fontSize = Math.floor(Math.min(size.w, size.h) * 0.8);
  // 初始职业/怪物/NPC 不发光，仅品質系统通过CSS class加光
  const baseFilter = 'drop-shadow(0 2px 3px rgba(0,0,0,0.8))';
  const isImg = !!s.useImg;
  const idleSrc = isImg ? s.idle : '';
  const multiFrame = !!s.multiFrame;
  const coverMode = !!s.coverMode;
  const emojiIdle = s.idle || '技';
  const emojiAttack = s.attack || s.idle || '技';
  // lean 模式：AI/怪物/召唤只用 1 张图（idle）+ CSS 动画，大幅减少 DOM
  // 只有玩家/英雄/变身用完整8帧结构
  // v2.4.0：有方向圖的單位疊加方向層
  const hasDir = hasDirectionalSprites(s);
  const dirDownSrc = hasDir ? getDirSpriteUrl(s, 'down') : '';
  const dirUpSrc = hasDir ? getDirSpriteUrl(s, 'up') : '';
  const dirSideSrc = hasDir ? getDirSpriteUrl(s, 'side') : '';
  const dirAttackSrc = hasDir ? getDirSpriteUrl(s, 'attack') : '';
  const dirClass = hasDir ? ' sprite-dir-mode dir-down' : '';
  
  const dirLayerHTML = hasDir ? `
    <div class="dir-sprite-layer">
      <img class="dir-sprite dir-down" src="${dirDownSrc}" style="filter:${baseFilter}" alt="" onerror="handleImgError(this)"/>
      <img class="dir-sprite dir-up" src="${dirUpSrc}" style="filter:${baseFilter}" alt="" onerror="handleImgError(this)"/>
      <img class="dir-sprite dir-left" src="${dirSideSrc}" style="filter:${baseFilter};transform:scaleX(-1)" alt="" onerror="handleImgError(this)"/>
      <img class="dir-sprite dir-right" src="${dirSideSrc}" style="filter:${baseFilter}" alt="" onerror="handleImgError(this)"/>
      <img class="dir-sprite dir-attack dir-attack-right" src="${dirAttackSrc}" style="filter:${baseFilter}" alt="" onerror="handleImgError(this)"/>
      <img class="dir-sprite dir-attack dir-attack-left" src="${dirAttackSrc}" style="filter:${baseFilter};transform:scaleX(-1)" alt="" onerror="handleImgError(this)"/>
    </div>
  ` : '';
  
  if (lean && isImg) {
    return `
      <div class="unit-info">
        <div class="unit-hp-bar"><div class="unit-hp-fill" style="width:100%"></div></div>
        <div class="unit-name"></div>
        <div class="unit-level-tag"></div>
      </div>
      <div class="unit-sprite-wrap ${coverMode ? 'sprite-cover-mode' : ''}${dirClass}" style="width:${size.w}px;height:${size.h}px;background:radial-gradient(ellipse at 50% 70%, rgba(100,70,40,0.25), transparent 70%);">
        ${hasDir ? '' : `<img class="unit-sprite-img sprite-frame-idle" src="${idleSrc}" style="filter:${baseFilter}" alt="" loading="lazy" onerror="handleImgError(this)"/>`}
        ${dirLayerHTML}
        <div class="unit-sprite-tomb" style="display:none"></div>
        <div class="slash-effect"></div>
      </div>
      <div class="unit-shadow"></div>
    `;
  }
  // 完整模式：8帧结构（玩家/英雄/变身）
  // v2.4.0-patch：恢復各 frame 真實圖片來源，動畫由 JS 幀切換 + 方向層雙重驅動
  const idleSrcComputed = isImg ? s.idle : '';
  const attackSrc = isImg ? (s.attack || s.idle) : '';
  const attack2Src = isImg ? (s.attack2 || s.attack || s.idle) : '';
  const walkSrc = isImg ? (s.walk || s.idle) : '';
  const walk2Src = isImg ? (s.walk2 || s.walk || s.idle) : '';
  const walk3Src = isImg ? (s.walk3 || s.walk || s.idle) : '';
  const walk4Src = isImg ? (s.walk4 || s.walk || s.idle) : '';
  const hitSrc = isImg ? (s.hit || s.attack || s.idle) : '';
  // onerror 統一使用全域 handleImgError：
  //   - 本地資源失敗 → 自動切換到 CDN
  //   - CDN 也失敗 → 隱藏圖片並為父層加上背景占位，避免顯示破裂圖示
  const onErrorHide = "handleImgError(this)";
  return `
    <div class="unit-info">
      <div class="unit-hp-bar"><div class="unit-hp-fill" style="width:100%"></div></div>
      ${kind === 'hero' ? '<div class="unit-mp-bar"><div class="unit-mp-fill" style="width:100%"></div></div>' : ''}
      <div class="unit-name"></div>
      <div class="unit-level-tag"></div>
    </div>
    <div class="unit-sprite-wrap ${coverMode ? 'sprite-cover-mode' : ''} ${multiFrame ? 'sprite-multi-frame' : ''} ${s.singleFrame ? 'sprite-single-frame' : ''}" style="width:${size.w}px;height:${size.h}px;background:radial-gradient(ellipse at 50% 70%, rgba(100,70,40,0.25), transparent 70%);">
      ${isImg ? `
        <img class="unit-sprite-img sprite-frame-idle" src="${idleSrc}" style="filter:${baseFilter}" alt="" onerror="${onErrorHide}"/>
        <img class="unit-sprite-img sprite-frame-walk sprite-frame-walk-1" src="${walkSrc}" style="filter:${baseFilter};display:none" alt="" onerror="${onErrorHide}"/>
        <img class="unit-sprite-img sprite-frame-walk sprite-frame-walk-2" src="${walk2Src}" style="filter:${baseFilter};display:none" alt="" onerror="${onErrorHide}"/>
        <img class="unit-sprite-img sprite-frame-walk sprite-frame-walk-3" src="${walk3Src}" style="filter:${baseFilter};display:none" alt="" onerror="${onErrorHide}"/>
        <img class="unit-sprite-img sprite-frame-walk sprite-frame-walk-4" src="${walk4Src}" style="filter:${baseFilter};display:none" alt="" onerror="${onErrorHide}"/>
        <img class="unit-sprite-img sprite-frame-attack sprite-frame-attack-1" src="${attackSrc}" style="filter:${baseFilter};display:none" alt="" onerror="${onErrorHide}"/>
        <img class="unit-sprite-img sprite-frame-attack sprite-frame-attack-2" src="${attack2Src}" style="filter:${baseFilter};display:none" alt="" onerror="${onErrorHide}"/>
        <img class="unit-sprite-img sprite-frame-hit" src="${hitSrc}" style="filter:${baseFilter};display:none" alt="" onerror="${onErrorHide}"/>
        <div class="unit-sprite-tomb">墓</div>
        <div class="slash-effect"></div>
        <div class="dust-particles"></div>
      ` : `
        <div class="unit-sprite-emoji" data-sprite-idle="${emojiIdle}" data-sprite-attack="${emojiAttack}" data-sprite-dead="墓" style="color:${color};font-size:${fontSize}px;filter:${baseFilter}">${emojiIdle}</div>
      `}
    </div>
    <div class="transform-aura" style="visibility:hidden;opacity:0;pointer-events:none;position:absolute;top:0;left:0;width:100%;height:100%;z-index:-1;overflow:visible">
      <div class="aura-glow-outer"></div>
      <div class="aura-smoke"><span></span><span></span><span></span><span></span><span></span><span></span><span></span><span></span></div>
      <div class="aura-lightning">
        <div class="bolt bolt-1" style="clip-path: polygon(50% 0%, 70% 25%, 45% 38%, 80% 62%, 55% 75%, 88% 100%, 30% 100%, 45% 79%, 20% 62%, 55% 42%, 25% 25%);background:linear-gradient(to bottom,#fff8d0,#ffc040,#a060ff);box-shadow:0 0 8px #ffd060,0 0 16px #a060ff;width:100%;height:100%"></div>
        <div class="bolt bolt-2" style="clip-path: polygon(45% 0%, 75% 21%, 50% 33%, 88% 54%, 60% 67%, 95% 100%, 25% 100%, 38% 75%, 12% 58%, 50% 40%, 20% 21%);background:linear-gradient(to bottom,#fff8d0,#ffc040,#a060ff);box-shadow:0 0 8px #ffd060,0 0 16px #a060ff;width:100%;height:100%"></div>
        <div class="bolt bolt-3" style="clip-path: polygon(55% 0%, 30% 23%, 63% 35%, 25% 57%, 60% 69%, 20% 100%, 80% 100%, 70% 77%, 88% 60%, 50% 42%, 80% 23%);background:linear-gradient(to bottom,#fff8d0,#ffc040,#a060ff);box-shadow:0 0 8px #ffd060,0 0 16px #a060ff;width:100%;height:100%"></div>
        <div class="bolt bolt-4" style="clip-path: polygon(40% 0%, 70% 18%, 38% 33%, 75% 50%, 45% 65%, 80% 100%, 25% 100%, 35% 73%, 15% 55%, 50% 37%, 25% 18%);background:linear-gradient(to bottom,#fff8d0,#ffc040,#a060ff);box-shadow:0 0 8px #ffd060,0 0 16px #a060ff;width:100%;height:100%"></div>
              </div>
    </div>
    <div class="unit-shadow"></div>
  `;
}

// 单张图模式：无需帧切换，动画全部由 CSS 类驱动
function setSpriteFrame(spriteEl, frameIdx, frameCount) {
  // 空函数：保留接口兼容，但不再做帧切换
  // 所有动画通过 .world-unit 的 idle/walking/attacking/hit/dead 类由 CSS 驱动
}

const SPRITE_SIZE = { hero: { w: 64, h: 80 }, enemy: { w: 50, h: 56 }, summon: { w: 46, h: 52 }, pet: { w: 38, h: 42 } };

// 初始化单位动画状态（8帧多帧模式：walk 4帧循环，attack 2帧序列，idle单帧呼吸，hit单帧）
function initUnitAnimState(uid) {
  unitAnimState.set(uid, {
    breathPhase: Math.random() * Math.PI * 2,
    animFrame: 0,        // 当前帧索引
    animTimer: 0,        // 当前帧剩余时间
    lastState: 'idle',   // 上一状态，用于状态切换时重置帧
  });
}

// 8帧动画每帧时长(ms)：walk 4帧来回循环(600ms周期)，attack 3帧序列(300ms)，hit 250ms
const ANIM_FRAME_DURATIONS = {
  // v2.4.0：8 幀標準（CSS 偽幀 + JS 幀切換雙系統）
  walk:   [75, 75, 75, 75, 75, 75, 75, 75], // 8 步來回，共 600ms
  attack: [62, 62, 62, 62, 62, 62, 62, 62], // 8 步攻擊，共 500ms
  hit:    [37, 37, 37, 37, 37, 37, 37, 41],  // 8 步受擊，共 300ms
  idle:   [200, 200, 200, 200, 200, 200, 200, 200], // 8 步呼吸，共 1.6s
};

// 切換精靈姿態：idle / walk / attacking / hit / dead 多種狀態
// 8帧模式下，帧由 unitAnimState.animFrame 驱动（gameLoop每帧调用updateAnimFrames）
// 效能最佳化：
//   1. 快取 frame 元素到 unitEl._frames 上，避免每幀 querySelectorAll
//   2. 畫面外單位跳過 frame 切換（CSS 暫停 + DOM 操作跳過）
//   3. 狀態與幀索引都沒變時，完全不操作 DOM
function applyUnitAnimFrame(unitEl, uid, state) {
  // 畫面外：跳過 frame 切換（節省 DOM 操作 + GPU 重繪）
  if (unitEl._offscreen) return;
  const anim = unitAnimState.get(uid);
  // 快取 frame 元素（首次才做 DOM 查詢）
  let frames = unitEl._frames;
  if (!frames) {
    const imgIdle = unitEl.querySelector('.sprite-frame-idle');
    if (!imgIdle) {
      // emoji 精靈模式：快速處理
      const emojiEl = unitEl.querySelector('.unit-sprite-emoji');
      if (!emojiEl) return;
      let emoji;
      if (state === 'dead') emoji = emojiEl.dataset.spriteDead || '\uD83E\uDEA6';
      else if (state === 'attacking' || state === 'casting') emoji = emojiEl.dataset.spriteAttack || emojiEl.dataset.spriteIdle;
      else emoji = emojiEl.dataset.spriteIdle || '\u2694\uFE0F';
      if (emojiEl.textContent !== emoji) emojiEl.textContent = emoji;
      return;
    }
    frames = {
      idle: imgIdle,
      walk: Array.prototype.slice.call(unitEl.querySelectorAll('.sprite-frame-walk')),
      attack: Array.prototype.slice.call(unitEl.querySelectorAll('.sprite-frame-attack')),
      hit: unitEl.querySelector('.sprite-frame-hit'),
      tomb: unitEl.querySelector('.unit-sprite-tomb'),
      lastState: null,
      lastFrame: -1,
    };
    unitEl._frames = frames;
  }

  const isDead = state === 'dead';
  const isAttack = state === 'attacking' || state === 'casting';
  const isWalk = state === 'walking' || state === 'chasing' || state === 'wandering';
  const isHit = state === 'hit';

  // 計算當前應顯示的幀索引
  let showFrame = 'idle';
  let showIdx = 0;
  if (isDead) { showFrame = 'tomb'; }
  else if (isHit) { showFrame = 'hit'; }
  else if (isAttack) { showFrame = 'attack'; showIdx = anim ? Math.min(anim.animFrame, frames.attack.length - 1) : 0; }
  else if (isWalk && frames.walk.length > 0) {
    showFrame = 'walk';
    const seq = frames.walk.length >= 3 ? [0, 1, 2, 1] : [0, 1, 0, 1];
    showIdx = anim ? seq[anim.animFrame % 4] : 0;
  }

  // 狀態與索引都沒變 → 跳過 DOM 操作
  if (frames.lastState === showFrame && frames.lastIdx === showIdx) return;

  // 全部隱藏再顯示目標（v2.4.0：只用 display 切換，絕不設 opacity/visibility 0 導致閃爍）
  frames.idle.style.display = 'none';
  for (let i = 0; i < frames.walk.length; i++) frames.walk[i].style.display = 'none';
  for (let i = 0; i < frames.attack.length; i++) frames.attack[i].style.display = 'none';
  if (frames.hit) frames.hit.style.display = 'none';
  if (frames.tomb) frames.tomb.style.display = 'none';

  const isFrameBroken = (el) => el && el.classList && el.classList.contains('frame-error');
  // v2.4.0：從當前索引往前找，找到第一個沒壞的 frame；找不到才退回 idle
  function findGoodFrame(arr, idx) {
    if (!arr || arr.length === 0) return null;
    const start = ((idx % arr.length) + arr.length) % arr.length;
    for (let i = 0; i < arr.length; i++) {
      const k = (start - i + arr.length) % arr.length;
      if (arr[k] && !isFrameBroken(arr[k])) return arr[k];
    }
    return null;
  }
  let target = null;
  if (showFrame === 'tomb') target = frames.tomb;
  else if (showFrame === 'hit') target = isFrameBroken(frames.hit) ? frames.idle : frames.hit;
  else if (showFrame === 'attack') {
    target = findGoodFrame(frames.attack, showIdx) || (isFrameBroken(frames.idle) ? frames.walk[0] : frames.idle);
  } else if (showFrame === 'walk') {
    target = findGoodFrame(frames.walk, showIdx) || frames.idle;
  } else {
    target = isFrameBroken(frames.idle) ? (frames.walk[0] || frames.idle) : frames.idle;
  }
  if (target) target.style.display = showFrame === 'tomb' ? 'flex' : 'block';

  frames.lastState = showFrame;
  frames.lastIdx = showIdx;
}

