function showCharCreate() {
  charCreateState = {
    classId: 'warrior',
    name: '',
    nameChecked: false,   // 是否通過重複確認
    nameCheckPending: false,
  };
  const screen = $('char-create-screen');
  if (screen) screen.classList.remove('hidden');
  initCC2UI();
}

function initCC2UI() {
  const classOrder = ['warrior', 'paladin', 'rogue', 'archer', 'mage', 'warlock'];
  const classRow = $('cc2-class-row');
  if (classRow) {
    classRow.innerHTML = '';
    classOrder.forEach(cid => {
      const sp = SPRITE[cid] || SPRITE.warrior;
      const detail = CLASS_DETAIL[cid];
      const wrap = document.createElement('div');
      wrap.style.display = 'flex';
      wrap.style.flexDirection = 'column';
      wrap.style.alignItems = 'center';
      wrap.style.cursor = 'pointer';
      
      const btn = document.createElement('button');
      btn.className = 'cc2-class-icon-btn' + (cid === charCreateState.classId ? ' active' : '');
      btn.dataset.classId = cid;
      btn.style.cursor = 'pointer';
      btn.title = detail.name + ' — 點擊選擇此職業';
      // v2.4.0：使用職業頭像 icon，加上邊框強化可點擊性
      const portraitUrl = 'assets/class/' + cid + '/portrait.jpg';
      if (sp.useImg && sp.idle) {
        btn.innerHTML = `<img src="${portraitUrl}" alt="${detail.name}" 
          style="width:100%;height:100%;object-fit:cover;border-radius:4px"
          onerror="this.style.display='none';var fb=this.parentElement.querySelector('.cc2-icon-fallback');if(fb)fb.style.display='flex';"/><span class="cc2-icon-fallback" style="display:none;position:absolute;inset:0;align-items:center;justify-content:center;color:#e8c060;font-size:14px;font-weight:700;letter-spacing:1px;text-shadow:0 1px 3px rgba(0,0,0,0.8);pointer-events:none">${detail.name.slice(0, 1)}</span>`;
      } else {
        btn.innerHTML = `<span class="cc2-icon-fallback" style="display:flex;position:absolute;inset:0;align-items:center;justify-content:center;color:#e8c060;font-size:14px;font-weight:700;letter-spacing:1px;text-shadow:0 1px 3px rgba(0,0,0,0.8)">${detail.name.slice(0, 1)}</span>`;
      }
      
      const label = document.createElement('span');
      label.className = 'cc2-class-label';
      label.textContent = detail.name;
      
      wrap.appendChild(btn);
      wrap.appendChild(label);
      
      btn.addEventListener('click', () => selectCC2Class(cid));
      classRow.appendChild(wrap);
    });
  }

  // 角色名輸入
  const nameInput = $('cc2-name-input');
  if (nameInput) {
    nameInput.addEventListener('input', () => {
      charCreateState.name = nameInput.value.trim();
      charCreateState.nameChecked = false; // 修改後需重新確認
      updateCC2NameStatus('', '');
      updateCC2CreateBtnState();
    });
    nameInput.addEventListener('keydown', e => {
      if (e.key === 'Enter') checkCC2Name();
    });
  }

  // 重複確認按鈕
  const checkBtn = $('cc2-check-btn');
  if (checkBtn) checkBtn.addEventListener('click', checkCC2Name);

  // 返回按鈕（關閉創角頁，回到角色選擇）
  const backBtn = $('cc2-back-btn');
  if (backBtn) {
    backBtn.addEventListener('click', () => {
      const screen = $('char-create-screen');
      if (screen) screen.classList.add('hidden');
      // 如果有外部設定的返回回調，呼叫它
      if (window.__onCharCreateBack && typeof window.__onCharCreateBack === 'function') {
        try { window.__onCharCreateBack(); } catch(e) {}
      }
    });
  }

  // 創建按鈕
  const createBtn = $('cc2-create-btn');
  if (createBtn) createBtn.addEventListener('click', confirmCC2CharCreate);

  // 首次渲染
  updateCC2Portrait();
  updateCC2TransformPreview();
  updateCC2ClassInfo();
  updateCC2CreateBtnState();
}

function selectCC2Class(cid) {
  if (charCreateState.classId === cid) return;
  charCreateState.classId = cid;
  
  // 更新 icon 選中樣式
  const classRow = $('cc2-class-row');
  if (classRow) {
    classRow.querySelectorAll('.cc2-class-icon-btn').forEach(b => {
      b.classList.toggle('active', b.dataset.classId === cid);
    });
  }
  
  // 更新介面各區塊
  updateCC2Portrait();
  updateCC2TransformPreview();
  updateCC2ClassInfo();
}

function updateCC2Portrait() {
  const portraitEl = $('cc2-portrait');
  if (!portraitEl) return;
  const cid = charCreateState.classId;
  const detail = CLASS_DETAIL[cid];
  // v2.4.0：使用職業立繪真圖（portrait.jpg），不再用精靈圖當大立繪
  const portraitUrl = 'assets/class/' + cid + '/portrait.jpg';
  
  portraitEl.innerHTML = `
    <div class="cc2-portrait-fallback" style="display:none">
      <div class="cc2-fallback-title">${detail ? detail.name : ''}</div>
      <div class="cc2-fallback-sub">${detail && CLASS_TRANSFORM_MAP[cid] ? CLASS_TRANSFORM_MAP[cid].name : '真系列金變'}</div>
    </div>
    <img src="${portraitUrl}" alt="${detail ? detail.name : ''}" class="cc2-portrait-img cc2-portrait-real" 
         style="display:none;object-fit:contain;width:100%;height:100%"
         onload="this.style.display='block';var fb=this.parentElement.querySelector('.cc2-portrait-fallback');if(fb)fb.style.display='none'"
         onerror="this.style.display='none';var fb=this.parentElement.querySelector('.cc2-portrait-fallback');if(fb)fb.style.display='flex'"/>
  `;
}

// 8 幀動畫播放（用於創角頁立繪輕微呼吸/待機效果）
let _cc2PortraitAnimTimer = null;
function startCC2PortraitAnim(img, frames) {
  if (_cc2PortraitAnimTimer) clearInterval(_cc2PortraitAnimTimer);
  if (!frames || frames.length < 2) return;
  let idx = 0;
  _cc2PortraitAnimTimer = setInterval(() => {
    idx = (idx + 1) % frames.length;
    if (img && img.src) img.src = frames[idx];
  }, 350);
}

function updateCC2ClassInfo() {
  const cid = charCreateState.classId;
  const detail = CLASS_DETAIL[cid];
  if (!detail) return;
  
  const nameEl = $('cc2-class-name');
  const descEl = $('cc2-class-desc');
  const weaponEl = $('cc2-main-weapon');
  const typeEl = $('cc2-combat-type');
  const traitEl = $('cc2-class-trait');
  
  if (nameEl) nameEl.textContent = detail.name;
  if (descEl) descEl.textContent = detail.desc;
  if (weaponEl) weaponEl.textContent = detail.mainWeapon;
  if (typeEl) typeEl.textContent = detail.combatType;
  if (traitEl) traitEl.textContent = detail.trait;
}

function updateCC2TransformPreview() {
  const cid = charCreateState.classId;
  const tf = CLASS_TRANSFORM_MAP[cid];
  if (!tf) return;
  
  const nameEl = $('cc2-transform-name');
  const descEl = $('cc2-transform-desc');
  const rarityEl = $('cc2-transform-rarity');
  const spriteEl = $('cc2-transform-sprite');
  
  if (nameEl) nameEl.textContent = tf.name;
  if (rarityEl) rarityEl.textContent = tf.rarity;
  
  // 從 TRANSFORM_POOL 拿 description
  const poolTf = TRANSFORM_POOL.find(t => t.id === tf.id);
  if (descEl) descEl.textContent = poolTf?.desc || '最強變身形態，全屬性大幅提升';
  
  // v2.4.0：變身預覽使用 portrait 立繪真圖
  if (spriteEl) {
    const portraitUrl = tf.portrait || (sp && sp.idle);
    if (portraitUrl) {
      spriteEl.innerHTML = `<img src="${portraitUrl}" alt="${tf.name}" class="cc2-transform-img cc2-transform-real" 
        style="object-fit:contain;width:100%;height:100%"
        onerror="this.parentElement.innerHTML='<div class=\\'cc2-transform-fallback\\'><div class=\\'cc2-tf-name\\'>${tf.name}</div></div>'"/>`;
    } else {
      spriteEl.innerHTML = `<div class="cc2-transform-fallback"><div class="cc2-tf-name">${tf.name}</div></div>`;
    }
  }
}

// ===== 角色名重複確認 =====
function checkCC2Name() {
  const name = charCreateState.name.trim();
  const statusEl = $('cc2-name-status');
  const checkBtn = $('cc2-check-btn');
  
  if (!name) {
    updateCC2NameStatus('請輸入角色名稱', 'error');
    return;
  }
  if (name.length < 2 || name.length > 10) {
    updateCC2NameStatus('角色名稱長度需為 2-10 個字元', 'error');
    return;
  }
  // 簡單敏感詞檢查
  const forbidden = ['管理員', 'GM', 'gm', '系統', '官方', '總裁', '皇帝', '天王'];
  for (const w of forbidden) {
    if (name.indexOf(w) !== -1) {
      updateCC2NameStatus('名稱含有違禁字詞，請重新輸入', 'error');
      return;
    }
  }
  
  charCreateState.nameCheckPending = true;
  charCreateState.nameChecked = false;
  updateCC2NameStatus('確認中...', 'checking');
  if (checkBtn) { checkBtn.disabled = true; }
  updateCC2CreateBtnState();
  
  // 嘗試透過後端查重；失敗則本機檢查
  const serverInfo = (window.AuthSystem && typeof window.AuthSystem.getCurrentServer === 'function')
    ? window.AuthSystem.getCurrentServer()
    : null;
  const serverId = serverInfo?.id || 'local';
  const apiPath = '/characters/check-name?name=' + encodeURIComponent(name) + '&server=' + encodeURIComponent(serverId);
  
  // 後端有 api 函式的話用之（在線模式）；否則本機檢查（離線模式）
  const apiFn = window.AuthSystem?.api || null;
  
  const checkLocal = () => {
    // 離線：檢查 localStorage 裡既有角色名
    let conflict = false;
    try {
      for (let i = 0; i < 4; i++) {
        const raw = localStorage.getItem('mmo_save_' + i);
        if (raw) {
          const data = JSON.parse(raw);
          if (data.name === name) { conflict = true; break; }
        }
      }
    } catch (e) {}
    if (conflict) {
      charCreateState.nameChecked = false;
      updateCC2NameStatus('此角色名稱已存在，請更換', 'error');
    } else {
      charCreateState.nameChecked = true;
      updateCC2NameStatus('此名稱可以使用', 'ok');
    }
    if (checkBtn) checkBtn.disabled = false;
    updateCC2CreateBtnState();
  };
  
  if (apiFn) {
    apiFn(apiPath).then(data => {
      if (data && typeof data.available === 'boolean') {
        if (data.available) {
          charCreateState.nameChecked = true;
          updateCC2NameStatus('此名稱可以使用', 'ok');
        } else {
          charCreateState.nameChecked = false;
          updateCC2NameStatus('此角色名稱已存在，請更換', 'error');
        }
      } else {
        checkLocal();
      }
      if (checkBtn) checkBtn.disabled = false;
      updateCC2CreateBtnState();
    }).catch(() => {
      // 後端不通 → 本機檢查
      checkLocal();
    });
  } else {
    // 沒有 api → 本機檢查
    setTimeout(checkLocal, 200);
  }
}

function updateCC2NameStatus(text, type) {
  const statusEl = $('cc2-name-status');
  if (!statusEl) return;
  statusEl.textContent = text || '';
  statusEl.className = 'cc2-name-status' + (type ? ' ' + type : '');
}

function updateCC2CreateBtnState() {
  const btn = $('cc2-create-btn');
  if (!btn) return;
  const name = charCreateState.name.trim();
  // v2.4.0：完成創建按鈕一律可按，只驗證名稱長度，不被健康檢查/查重結果擋住
  const valid = name.length >= 2 && name.length <= 10;
  btn.disabled = !valid;
}

// ===== 最終確認創建 =====
function confirmCC2CharCreate() {
  const name = charCreateState.name.trim();
  if (!name) {
    updateCC2NameStatus('請輸入角色名稱', 'error');
    return;
  }
  if (name.length < 2 || name.length > 10) {
    updateCC2NameStatus('角色名稱長度需為 2-10 個字元', 'error');
    return;
  }
  // 簡單敏感詞檢查
  const forbidden = ['管理員', 'GM', 'gm', '系統', '官方', '總裁', '皇帝', '天王'];
  for (const w of forbidden) {
    if (name.indexOf(w) !== -1) {
      updateCC2NameStatus('名稱含有違禁字詞，請重新輸入', 'error');
      return;
    }
  }
  
  const cid = charCreateState.classId;
  const cls = CLASSES[cid];
  if (!cls) return;
  
  // v2.4.0：建立 loading 狀態，避免重複點擊
  const createBtn = $('cc2-create-btn');
  const originBtnText = createBtn ? createBtn.textContent : '';
  if (createBtn) { createBtn.disabled = true; createBtn.textContent = '創建中...'; }
  updateCC2NameStatus('正在創建角色，請稍候...', 'checking');
  
  // 根據職業預設屬性自動分配（玩家不用手動配點）
  const pref = CLASS_STAT_PREFS[cid] || CLASS_STAT_PREFS.warrior;
  GS.player.name = name;
  GS.player.classId = cid;
  GS.player.created = true;  // v2.4.0：標記角色已創建，下次直接進世界
  
  // 計算初始屬性（基於職業偏好 + 基礎值）
  const s = pref;
  const strBonus = (s.str - 10) * 1.5;
  const conBonus = (s.con - 10) * 8;
  const dexBonus = (s.dex - 10) * 0.5;
  GS.player.atk = Math.floor(Number(cls.baseStats.atk) + strBonus);
  GS.player.def = Math.floor(Number(cls.baseStats.def) + dexBonus * 0.5);
  GS.player.hpMax = Math.floor(Number(cls.baseStats.hpMax) + conBonus);
  GS.player.hp = GS.player.hpMax;
  GS.player.crit = Math.floor(Number(cls.baseStats.crit || 5) + dexBonus * 0.3);
  GS.player.baseStats6 = { ...pref };
  
  // 進入世界的共用流程
  function enterWorld() {
    // 關閉創建介面並重置表單（v2.5.6：確保不留空白面板）
    const screen = $('char-create-screen');
    if (screen) {
      screen.classList.add('hidden');
      // 重置表單狀態
      const nameInput = screen.querySelector('#cc2-name-input');
      if (nameInput) nameInput.value = '';
      charCreateState = { classId: 'warrior', name: '', statPoints: 5,
        str: 10, con: 10, dex: 10, int: 10, luk: 10, vit: 10 };
    }

    // v2.5.6：確保遊戲完整初始化（game loop + 事件 + 精靈 + 地圖）
    //  新創角時從此進入；冪等：若已初始化過則直接返回
    init();

    // 更新介面
    if (el.topName) el.topName.textContent = name;
    if (el.classBadge) el.classBadge.textContent = cls.name;
    updatePlayerSprite();
    updateTransformVisual();
    updateUI();
    updateSkillBar();
    updateSlotDisplay();
    const topAvatarEl = $('top-avatar');
    if (topAvatarEl) {
      topAvatarEl.innerHTML = spriteEmojiHTML(cls.sprite, 36);
    }
    addLog('system', '歡迎來到君主之刃，' + name + '！');
    addLog('system', '點擊地面移動，點擊菜單按鈕查看國家/公會/城堡。');
    
    // 初始化音訊系統
    if (window.AudioSystem) {
      try {
        AudioSystem.init();
        AudioSystem.ensureRunning();
        AudioSystem.startMusic(GS.currentMap);
      } catch (e) { console.warn('[Audio] 初始化異常', e); }
    }
    
    // 全局 AI 池初始化
    setTimeout(() => {
      try { initGlobalAIPool(); } catch(e) {
        console.error('[AI System] AI初始化失敗，已跳過：', e);
        addLog('system', '! AI玩家系統初始化異常，已跳過');
      }
    }, 1000);
    
    // 國家選擇
    if (!GS.nation) showNationSelect();

    // v2.4.0：角色建立完成回調（供角色選擇頁刷新列表用）
    // 若有外部 callback（auth.js 設定），呼叫它並傳回角色資訊
    if (window.__onCharCreated && typeof window.__onCharCreated === 'function') {
      try {
        window.__onCharCreated({
          name: name,
          classId: cid,
          level: GS.player.level || 1,
          className: cls.name,
        });
        window.__onCharCreated = null; // 一次性
      } catch(e) { console.warn('[CharCreate] callback error:', e); }
    }

    // 確保遊戲畫面顯示（從角色選擇頁進入時 game-root 可能還是 hidden）
    const gameRoot = document.getElementById('game-root');
    if (gameRoot) gameRoot.classList.remove('game-hidden');
  }
  
  // v2.4.0：直接 POST /api/characters/create，成功進世界；失敗顯示具體錯誤並恢復按鈕
  const apiFn = window.AuthSystem?.api || null;
  const serverInfo = (window.AuthSystem && typeof window.AuthSystem.getCurrentServer === 'function')
    ? window.AuthSystem.getCurrentServer()
    : null;
  const serverId = serverInfo?.id || 'local';
  
  if (apiFn) {
    apiFn('/characters/create', {
      name: name,
      classId: cid,
      server: serverId,
    }).then(result => {
      if (result && result.ok) {
        // v2.5.0：記錄當前角色索引，確保存檔寫對槽位
        GS.currentCharIdx = result.idx != null ? result.idx : 0;
        try { localStorage.setItem('mmo_char_idx', String(GS.currentCharIdx)); } catch(e) {}
        enterWorld();
      } else {
        // server 回 ok:false 或非預期格式，顯示具體錯誤
        const msg = result?.error || result?.message || '創建失敗，請重試';
        updateCC2NameStatus(msg, 'error');
        if (createBtn) { createBtn.disabled = false; createBtn.textContent = originBtnText; }
      }
    }).catch(err => {
      // v2.4.0：真失敗才提示，用伺服器具體錯誤訊息，不用靜態模式文字擋人
      const msg = err?.message || '網路異常，請稍後重試';
      updateCC2NameStatus(msg, 'error');
      if (createBtn) { createBtn.disabled = false; createBtn.textContent = originBtnText; }
    });
  } else {
    // 沒有 api → 直接進入（離線模式，localStorage 存檔）
    enterWorld();
  }
}

function showNationSelect() {
  let modal = document.getElementById('nation-select-modal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'nation-select-modal';
    modal.className = 'nation-select-modal';
    document.body.appendChild(modal);
  }
  modal.innerHTML = `
    <div class="nation-select-inner">
      <div class="nation-select-title">選擇你的國家</div>
      <div class="nation-select-subtitle">每個國家都有獨特的歷史與盟友</div>
      <div class="nation-select-grid">
        ${NATIONS.map(n => {
          const dotBg = { kent: 'radial-gradient(circle at 30% 30%,#ff6060,#a01010)', oren: 'radial-gradient(circle at 30% 30%,#60a0ff,#103080)', dion: 'radial-gradient(circle at 30% 30%,#60d060,#106020)', aden: 'radial-gradient(circle at 30% 30%,#ffd060,#a07010)' }[n.id];
          const borderColor = { kent: '#c02020', oren: '#4080ff', dion: '#40c060', aden: '#ffc040' }[n.id];
          return `
          <div class="nation-card" data-nation="${n.id}">
            <div class="nation-card-flag" data-flag="${n.id}" style="width:64px;height:64px;margin:0 auto;border-radius:50%;border:2px solid rgba(240,192,64,0.5);overflow:hidden;box-shadow:0 0 12px rgba(240,192,64,0.3);background:${dotBg};border-color:${borderColor}"></div>
            <div class="nation-card-name">${n.name}</div>
            <div class="nation-card-desc">${n.desc}</div>
          </div>`;
        }).join('')}
      </div>
      <button class="nation-select-skip" id="nation-select-skip">暫不選擇，稍後再加入</button>
    </div>
  `;
  // 動態注入國旗圖片，失敗則保留CSS背景圓點
  modal.querySelectorAll('[data-flag]').forEach(div => {
    const nid = div.dataset.flag;
    const img = new Image();
    img.src = NATION_FLAGS[nid] || NATION_FLAGS.kent;
    img.style.cssText = 'width:100%;height:100%;object-fit:cover;display:block';
    img.onload = () => { div.innerHTML = ''; div.appendChild(img); };
    img.onerror = () => { /* 保留 CSS 背景圓點 */ };
  });
  modal.style.display = 'flex';

  modal.querySelectorAll('.nation-card').forEach(card => {
    card.addEventListener('click', () => {
      const nid = card.dataset.nation;
      const nation = NATIONS.find(n => n.id === nid);
      if (nation) {
        GS.nation = nid;
        addLog('system', `你加入了【${nation.name}】！`);
        // v1.4.3 修正：加入國家後不自動加入任何軍團
        // 軍團必須由玩家手動申請 / 接受邀請 / 創建才會加入
        GS.guild = null;
        GS.guildId = null;
        GS.legionId = null;
        addLog('system', '你尚未加入任何軍團，可在「國家→軍團」頁面申請或創建軍團。');
        modal.style.display = 'none';
        updateUI();
      }
    });
  });
  const skipBtn = modal.querySelector('#nation-select-skip');
  if (skipBtn) skipBtn.addEventListener('click', () => {
    modal.style.display = 'none';
    addLog('system', '你可以在侧边選單「國家」页面中随时選擇加入國家。');
  });
}

// v2.4.0：舊創角模態 class-select-modal 已移除，統一使用 char-create-screen（羊皮紙樣式）

// 金/紫變身新精靈圖（帶閃電冒煙效果）
// ==================== 玩家渲染 ====================
function getPlayerSprite() {
  try {
    // 變身狀態：直接從 SPRITE 取變身專屬圖資
    if (GS.player?.transformId) {
      const tf = TRANSFORM_POOL.find(t => t.id === GS.player.transformId);
      if (tf && tf.spriteKey) {
        const spriteKey = tf.spriteKey.replace(/^t_/, '');
        const s = SPRITE[spriteKey];
        if (s) {
          console.log('[getPlayerSprite] 变身:', tf.name, '| sprite:', spriteKey);
          return s;
        }
        // fallback: 舊式 getTransformSprite
        const s2 = getTransformSprite(tf.spriteKey);
        if (s2) return s2;
      }
    }
    // 职业映射：完全走 resolveClassId → SPRITE 显式映射，绝不静默fallback
    const rawClassId = GS.player?.classId;
    const cls = resolveClassId(rawClassId);
    const sp = SPRITE[cls];
    console.log('[getPlayerSprite] SPRITE DEBUG',
                'rawClassId=', rawClassId,
                '| type=', typeof rawClassId,
                '| cls=', cls,
                '| SPRITE keys sample:', Object.keys(SPRITE).slice(0, 10),
                '| SPRITE[cls]存在:', !!sp,
                '| idle:', sp?.idle);
    if (!sp) {
      console.warn('[getPlayerSprite] 未找到职业精灵:', cls, 'classId原始值:', rawClassId, 'fallback到warrior');
      return SPRITE.warrior;
    }
    return sp;
  } catch(e) {
    console.warn('[getPlayerSprite] 异常:', e);
    return SPRITE.warrior;
  }
}

