window.enterSiegeBattle = function(castleId) {
  console.log('[Siege] enterSiegeBattle 调用，castleId=', castleId);
  if (!castleId) return;
  const siegeMapId = 'siege_' + castleId;
  const allMaps = getAllMaps();
  if (!allMaps[siegeMapId]) { alert('找不到該城堡的攻城戰場'); return; }
  // 關閉所有打開的面板 / 分欄 / 彈窗
  closeMapModal?.();
  // 1. 關閉國家/軍團側邊面板
  const sidePage = document.getElementById('side-page');
  if (sidePage) {
    sidePage.classList.remove('open');
    sidePage.style.display = 'none';
  }
  // 2. 關閉可能殘留的國家選擇、城堡、軍團等彈窗
  const closeIds = [
    'nation-select-modal', 'guild-modal', 'castle-modal', 'siege-modal',
    'legion-modal', 'nation-modal', 'player-menu', 'context-menu',
    'item-detail-modal', 'shop-modal', 'bag-modal',
  ];
  closeIds.forEach(id => {
    const el = document.getElementById(id);
    if (el) el.style.display = 'none';
  });
  // 3. 清除所有 z-index >= 100 的彈窗與遮罩層（避免半透明遮罩殘留）
  document.querySelectorAll('[class*="overlay"], [class*="modal"], [class*="popup"], [class*="dialog"]').forEach(el => {
    const z = parseInt(window.getComputedStyle(el).zIndex) || 0;
    const id = el.id || '';
    // 跳過世界場景本身的 overlay（如 game-overlay / world-overlay）
    if (id === 'game-overlay' || id === 'world-overlay' || id === 'ui-overlay') return;
    if (z >= 100 || el.classList.contains('modal-overlay') || el.classList.contains('mask')) {
      el.style.display = 'none';
    }
  });
  // 4. 重置頁面狀態
  if (typeof GS !== 'undefined') {
    GS.currentPage = null;
    GS.gachaPageTab = 'hero';
  }
  // 5. 關閉地圖彈窗
  const mapModal = document.getElementById('map-modal');
  if (mapModal) mapModal.style.display = 'none';
  loadMap(siegeMapId);
};

window.addEventListener('load', function() {
  // v2.0：若有帳號系統，先顯示官方首頁/登入，待玩家進入角色後再啟動遊戲
  if (window.AuthSystem) {
    AuthSystem.init();
    // 遊戲進入點由 AuthSystem 觸發
    window.onAuthReady = function(server) {
      // v2.5.5：登入後先重置 GS，避免上一帳號/上一角色的記憶體狀態殘留
      if (window.__resetGameState) window.__resetGameState();

      // v2.4.0 修復：若剛完成創角（auth.js 寫入 mmo_new_char），用其資料初始化
      let isNewChar = false;
      try {
        const raw = localStorage.getItem('mmo_new_char');
        if (raw) {
          const nc = JSON.parse(raw);
          if (!GS.player) GS.player = {};
          if (nc.name) GS.player.name = nc.name;
          if (nc.classId) GS.player.classId = nc.classId;
          GS.player.created = true;
          GS.player.level = nc.level || 1;
          GS.player.exp = 0;
          localStorage.removeItem('mmo_new_char');
          isNewChar = true;
          console.log('[Auth] 新創角色載入:', GS.player.name, '/', GS.player.classId);
        }
      } catch (e) { console.warn('[Auth] 讀取新創角色失敗:', e); }

      // v2.5.5：從後端載入角色存檔作為權威來源
      //   連線模式必須以伺服器回傳的 saveData 為準，絕不 fallback 到本機舊存檔
      try {
        const idxStr = localStorage.getItem('mmo_char_idx');
        const idx = idxStr != null ? parseInt(idxStr, 10) : 0;
        GS.currentCharIdx = isNaN(idx) ? 0 : idx;

        if (isNewChar) {
          // 新創角色：沒有存檔，直接初始化（伺服器為權威，本機只是快取）
          console.log('[存檔] 新創角色，跳過本機存檔載入');
        } else {
          // 既有角色：從伺服器權威載入（由 auth.js 的 startGameWithChar 已預載到槽位 key）
          const slotKey = getSlotSaveKey(GS.currentCharIdx);
          let loaded = false;
          if (slotKey) {
            const raw = localStorage.getItem(slotKey);
            if (raw) {
              const data = JSON.parse(raw);
              applySaveData(data);
              console.log('[存檔] 從帳號角色槽 ' + slotKey + ' 載入成功');
              loaded = true;
            }
          }
          if (!loaded) {
            // 離線模式 fallback
            loadGame();
          }
        }
      } catch(e) {
        console.warn('[存檔] 角色槽載入失敗:', e);
      }
      init();
    };
  } else {
    init();
  }
});

    // v2.5.5：登出 / 換帳號 / 換角色前，完整重置 GS 到初始狀態
    //   確保新帳號/新角色絕不繼承上一帳號的任何記憶體狀態
    window.__resetGameState = function() {
      try {
        // 重置所有 SAVE_FIELDS 到預設值（以 GS_INIT 為藍本）
        const defaults = {
          player: null,
          resources: { gold: 0, gem: 0 },
          currentMap: null,
          ownedHeroes: [],
          ownedPets: [],
          ownedTransforms: [],
          equippedHeroId: null,
          equippedPetId: null,
          equipment: { weapon: null, armor: null, helmet: null, boots: null, ring: null, necklace: null },
          inventory: [],
          bagMaxSlots: 30,
          enhanceTickets: 0,
          bagPage: 0,
          autoMode: false,
          autoSkillEnabled: true,
          autoPotionEnabled: true,
          autoMpEnabled: true,
          autoBuyPotion: false,
          autoItems: [],
          autoPvpMode: false,
          killCount: 0,
          quest: null,
          heroPageTab: 0,
          gachaPageTab: 0,
          shopTab: 0,
          menuPage: 0,
          nation: null,
          legionId: null,
          legionRank: null,
          nationContribution: 0,
          nationSkillLevels: {},
          todayDonatedGold: 0,
          todayDonatedGem: 0,
          nationTab: 0,
          membersSubTab: 0,
          transformRarity: 'rare',
          heroRarity: 'rare',
          petRarity: 'rare',
          castleTreasuries: {},
          gemTaxPool: {},
          siegeStats: {},
          weeklyTaxSettled: false,
          warDeclareDate: 0,
          warDeclareCount: 0,
          warDeclared: false,
          warCooldowns: {},
          rankings: { level: [], power: [], wealth: [], kills: [] },
          transformEndTime: 0,
          transformTicketEndTimes: [],
          boughtTrueDeathPack: false,
          monsters: [],
          aiPlayers: [],
          siegeWar: null,
          guild: null,
          currentCharIdx: null,
        };
        Object.keys(defaults).forEach(k => { GS[k] = JSON.parse(JSON.stringify(defaults[k])); });
        console.log('[ClearState] GS 已完全重置為初始狀態');
      } catch (e) {
        console.warn('[ClearState] 重置 GS 失敗:', e);
      }
    };
    // v2.4.0：登出 / 換帳號時清空所有遊戲狀態
    // 確保換帳號登入後只顯示該帳號從 server 取到的角色，A 帳角色不會殘留到 B 帳
    window.__clearGameState = function() {
      try {
        // v2.5.5：改用完整重置，不留任何殘留欄位
        if (window.__resetGameState) window.__resetGameState();
        // 清空 DOM 世界層元素
    const wl = document.getElementById('world-layer');
    if (wl) wl.innerHTML = '';
    const nl = document.getElementById('npc-layer');
    if (nl) nl.innerHTML = '';
    // 關閉所有彈窗
    document.querySelectorAll('.modal.open, .panel.open, .screen:not(.hidden)').forEach(el => {
      el.classList.remove('open');
      if (el.id !== 'game-root') el.classList.add('hidden');
    });
  } catch (e) {
    console.warn('[ClearState] 清空失敗:', e);
  }
};
window.__debugCreateChar = function(classId, name) {
  if (!name) name = '測試' + classId;
  // 先重置charCreateState為該職業屬性傾向
  if (window.__resetCharCreateStats) window.__resetCharCreateStats(classId);
  charCreateState.classId = classId;
  charCreateState.name = name;
  // 直接強行調用confirmCharCreate
  confirmCharCreate();
  const unit = worldLayer.querySelector('.world-unit.hero');
  const idleImg = unit?.querySelector('.sprite-frame-idle');
  const walk1 = unit?.querySelector('.sprite-frame-walk-1');
  return {
    classId: GS.player.classId,
    idle: idleImg?.src?.split('/').slice(-2).join('/'),
    walk1: walk1?.src?.split('/').slice(-2).join('/'),
  };
};
window.__debugVerifyAllClasses = function() {
  const classes = ['warrior','mage','archer','rogue','paladin'];
  const results = {};
  classes.forEach(cls => {
    const r = window.__debugCreateChar(cls);
    results[cls] = r;
  });
  console.log('========== 5職業創建-結果 ==========', results);
  return results;
};

